#include "global.h"
#include "event_data.h"
#include "string_util.h"
#include "characters.h"
#include "menu.h"
#include "script_menu.h"
#include "constants/flags.h"
#include "constants/vars.h"
#include "constants/opponents.h"

// Topaze: JOURNAL (Start menu). Objectives sorted in sections, with a done mark; data in src/data/topaze_journal.h
// (generated by docs/topaze/journal_gen.py). Two-level dynamic multichoice driven by EventScript_Journal.
#define JOURNAL_MAX_ROWS 8
#define JK_FLAG    0
#define JK_VAR     1
#define JK_TRAINER 2

struct TopazeJournalSection
{
    const u8 *name;
    u16 gate; // 0 = always visible
};

struct TopazeJournalEntry
{
    u8 section;
    u8 kind;
    u16 id;
    u16 val;
    const u8 *name;
    const u8 *hint;
};

#include "data/topaze_journal.h"

#define NUM_SECTIONS ARRAY_COUNT(sJournalSections)
#define NUM_ENTRIES  ARRAY_COUNT(sJournalEntries)

struct MenuAction gTopazeJournalMenu[JOURNAL_MAX_ROWS];
u8 gTopazeJournalCount;
static u8 sRowText[JOURNAL_MAX_ROWS][32];
static u8 sRowMap[JOURNAL_MAX_ROWS];
static u8 sCurSection;
static const u8 sDoneText[] = _("\nCompleted.");

static bool8 EntryDone(const struct TopazeJournalEntry *e)
{
    switch (e->kind)
    {
    case JK_VAR:
        return VarGet(e->id) >= e->val;
    case JK_TRAINER:
        return FlagGet(TRAINER_FLAGS_START + e->id);
    default:
        return FlagGet(e->id);
    }
}

static bool8 SectionVisible(u8 s)
{
    return sJournalSections[s].gate == 0 || FlagGet(sJournalSections[s].gate);
}

static void CountSection(u8 s, u8 *done, u8 *total)
{
    u16 i;
    *done = 0;
    *total = 0;
    for (i = 0; i < NUM_ENTRIES; i++)
    {
        if (sJournalEntries[i].section != s)
            continue;
        (*total)++;
        if (EntryDone(&sJournalEntries[i]))
            (*done)++;
    }
}

// VAR_RESULT = number of rows (sections)
void TopazeJournalBuildSections(void)
{
    u8 s, n = 0, done, total;
    u8 *p;

    for (s = 0; s < NUM_SECTIONS && n < JOURNAL_MAX_ROWS; s++)
    {
        if (!SectionVisible(s))
            continue;
        CountSection(s, &done, &total);
        p = StringCopy(sRowText[n], sJournalSections[s].name);
        *p++ = CHAR_SPACE;
        *p++ = CHAR_SPACE;
        p = ConvertIntToDecimalStringN(p, done, STR_CONV_MODE_LEFT_ALIGN, 2);
        *p++ = CHAR_SLASH;
        p = ConvertIntToDecimalStringN(p, total, STR_CONV_MODE_LEFT_ALIGN, 2);
        *p = EOS;
        gTopazeJournalMenu[n].text = sRowText[n];
        sRowMap[n] = s;
        n++;
    }
    gTopazeJournalCount = n;
    gSpecialVar_Result = n;
}

// VAR_RESULT = chosen row of the section list
void TopazeJournalPickSection(void)
{
    sCurSection = sRowMap[gSpecialVar_Result];
}

// VAR_RESULT = number of rows (entries of the current section); "+" = done, "-" = to do
void TopazeJournalBuildEntries(void)
{
    u16 i;
    u8 n = 0;
    u8 *p;

    for (i = 0; i < NUM_ENTRIES && n < JOURNAL_MAX_ROWS; i++)
    {
        if (sJournalEntries[i].section != sCurSection)
            continue;
        p = sRowText[n];
        *p++ = EntryDone(&sJournalEntries[i]) ? CHAR_PLUS : CHAR_HYPHEN;
        *p++ = CHAR_SPACE;
        p = StringCopyN(p, sJournalEntries[i].name, 22);
        *p = EOS;
        gTopazeJournalMenu[n].text = sRowText[n];
        sRowMap[n] = i;
        n++;
    }
    gTopazeJournalCount = n;
    gSpecialVar_Result = n;
}

// VAR_RESULT = chosen row; the text to display is left in gStringVar4
void TopazeJournalShowEntry(void)
{
    const struct TopazeJournalEntry *e = &sJournalEntries[sRowMap[gSpecialVar_Result]];

    if (EntryDone(e))
    {
        u8 *p = StringCopy(gStringVar4, e->name);
        StringCopy(p, sDoneText);
    }
    else
    {
        StringCopy(gStringVar4, e->hint);
    }
}
